package br.com.tapeteskalke.service; import br.com.tapeteskalke.dto.OperacaoDtos.DespesaRequest; import br.com.tapeteskalke.entity.Despesa; import br.com.tapeteskalke.repository.DespesaRepository; import java.util.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class DespesaService { private final DespesaRepository repo; private final AuditService audit; public DespesaService(DespesaRepository repo,AuditService audit){this.repo=repo;this.audit=audit;} @Transactional public Despesa create(DespesaRequest r){var d=new Despesa();d.setTipo(r.tipo());d.setDescricao(r.descricao());d.setValor(r.valor());d.setDataDespesa(r.dataDespesa());d.setObservacoes(r.observacoes());audit.created(d);return repo.save(d);} @Transactional(readOnly=true) public List<Despesa> list(){return repo.findAllByOrderByDataDespesaDesc();} }